from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import json,re,hashlib
base=Path('reports/research/510300_industrial_remaining_five_original_carriers_v1')
def now():return datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()
def readj(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def infer(title):
 s=re.sub(r'\s+','',title)
 m=re.search(r'^(20\d{2})年1[-—–至~]([0-9]{1,2})月',s)
 if m:return m.group(1)+'M'+m.group(2).zfill(2)
 m=re.search(r'^(20\d{2})年',s)
 if m and '规模以上工业企业' in s and '利润' in s and not re.search(r'\d月|解读|统计师|工业司',s):return m.group(1)+'M12'
 return None
proto=readj(base/'protocol.json');targets=proto['target_original_periods'];allh=[]
for i in [1,2]:
 p=base/f'原五官方查询批{i}实际回执.json';s=readj(p)['actual_tool_result']
 ms=list(re.finditer(r'(?m)^([^\n]+?)\s+\((https?://[^\s)]+)\)\s*$',s))
 for j,m in enumerate(ms):
  excerpt=s[m.end():ms[j+1].start() if j+1<len(ms) else len(s)]
  title=m.group(1);title_choices=[title]+re.findall(r'#{1,3}\s+(20\d{2}年[^\n]+)',excerpt)
  t=next((t for t in title_choices if infer(t)),None)
  if not t and title=='国家统计局信息公开':
   t=next((z for z in re.findall(r'(20\d{2}年全国规模以上工业企业[^\n]{0,120})',excerpt) if infer(z)),None)
  period=infer(t) if t else None
  allh.append({'original_header_title':title,'actual_original_title_candidate':t or 'UNKNOWN','url':m.group(2),'resolved_period':period,'source_query_receipt':p.as_posix(),'source_query_sha256':sha(p),'original_result_excerpt':excerpt})
cached={}
e88=Path('reports/research/510300_industrial_multidimensional_cash_constraint_source_v1/原首批5当前原全文与取得回执.json')
for r in readj(e88)['targets']:cached[r['url']]={'path':r['html_path'],'sha256':r['sha256'],'full_text_path':r['text_path']}
e92=Path('reports/research/510300_industrial_complete_original_source_followthrough_v1')
for r in readj(e92/'全部第一候选原报告实际取得回执.json')['reports']:cached[r['url']]={'path':r['path'],'sha256':r['sha256'],'full_text_path':r['full_text_path']}
x=readj(e92/'同查询修正及同原期不同口径载体实际取得回执.json')
for r in x['reports']+x['cached_reuses']:cached[r['url']]={'path':r['path'],'sha256':r['sha256'],'full_text_path':r['full_text_path']}
located=[]
for p in targets:
 hs=[h for h in allh if h['resolved_period']==p and re.match(r'https://[^/]*(?:stats\.gov\.cn|gov\.cn)/',h['url']) and not any(z in h['actual_original_title_candidate'] for z in ['解读','统计师','工业司'])]
 hs.sort(key=lambda h:(h['url'] in cached,0 if 'stats.gov.cn/sj/zxfb/' in h['url'] else 1 if 'app.www.gov.cn' in h['url'] else 2))
 seen=set();selected=[]
 for h in hs:
  if h['url'] in seen:continue
  seen.add(h['url']);r={**h,'economic_period':p}
  if h['url'] in cached:r['cached_reuse']=cached[h['url']]
  selected.append(r)
  if len(selected)==2:break
 located.append({'economic_period':p,'candidates':selected,'locator_status':'ACTUAL_ORIGINAL_PERIOD_FOUND' if selected else 'UNKNOWN_NOT_LOCATED_IN_FIVE_QUERIES'})
out={'at':now(),'queries_actual':5,'all_actual_headers':allh,'fixed_targets':located,'selected_new_first_GETs':[{**r,'raw_file_stem':r['economic_period']+'_候选'+str(j+1)} for t in located for j,r in enumerate(t['candidates']) if 'cached_reuse' not in r],'cached_reuses':[r for t in located for r in t['candidates'] if 'cached_reuse' in r],'unknown_not_deleted':True,'new_stock_labels':0,'new_model_fits':0}
p=base/'五期真实候选来源请求前登记.json';assert not p.exists();p.write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'候选期':[(r['economic_period'],[(h['url'],'原缓存' if 'cached_reuse' in h else '新实际原链接') for h in r['candidates']]) for r in located],'实际候选标题数量':len(allh),'新增原GET登记':len(out['selected_new_first_GETs']),'新金融':0},ensure_ascii=False),flush=True)
